      const content = [
        JSON.stringify({ ts: 1000, seq: 0, type: 'session.start', session_id: sessionId, data: null }),
        'invalid json line',
        JSON.stringify({ ts: 2000, seq: 1, type: 'session.end', session_id: sessionId, data: null }),
