    });

    it('should preserve optional trace_id', async () => {
      const event = await appendEvent(testDir, {
        type: 'session.start',
        session_id: sessionId,
        trace_id: 'trace-abc-123',
        data: null,
      });

      expect(event.trace_id).toBe('trace-abc-123');
