      await appendEvent(testDir, {
        type: 'session.start',
        session_id: sessionId,
        ts: 1000,
        data: null,
      });

      await appendEvent(testDir, {
        type: 'prompt.sent',
        session_id: sessionId,
        ts: 2000,
        data: null,
