        type: 'session.start',
        session_id: sessionId,
        ts: 1000,
        data: null,
      });

      await appendEvent(testDir, {
        type: 'prompt.sent',
        session_id: sessionId,
        ts: 2000,
        data: null,
      });

      await appendEvent(testDir, {
        type: 'session.end',
        session_id: sessionId,
        ts: 3000,
        data: null,
