      });

      await appendEvent(testDir, {
        type: 'session.end',
        session_id: sessionId,
        data: { reason: 'completed' },
      });

      const lastEvent = await getLastEvent(testDir, sessionId);

      expect(lastEvent).not.toBeNull();
      expect(lastEvent?.type).toBe('session.end');
