describe('Path helpers', () => {
  const specDir = '/test/.kspec';
  const sessionId = '01KF123456789ABCDEFGHJKMNP';

  it('should construct sessions directory path', () => {
    expect(getSessionsDir(specDir)).toBe('/test/.kspec/sessions');
  });

