      ended_at: '2026-01-20T11:00:00.000Z',
    }));
    await fs.writeFile(path.join(s1Dir, 'events.jsonl'), [
      JSON.stringify({
        ts: 1000,
        seq: 0,
        type: 'session.start',
        session_id: s1,
        data: { message: 'Starting session' },
      }),
      JSON.stringify({
