  const sessionId2 = testUlid('SESS', 2);

  beforeEach(async () => {
    tempDir = await setupTempFixtures();

    // In traditional mode (no shadow branch), specDir = tempDir
    const sessionsDir = path.join(tempDir, 'sessions');
