    // Session 1: completed with events and context
    const s1Dir = path.join(sessionsDir, sessionId1);
    await fs.mkdir(s1Dir);
    await fs.writeFile(path.join(s1Dir, 'session.yaml'), YAML.stringify({
      id: sessionId1,
      agent_type: 'claude-agent-acp',
