    await fs.writeFile(path.join(s1Dir, blobRelPath), blobContent, 'utf-8');
    await fs.writeFile(path.join(s1Dir, 'events.jsonl'), [
      JSON.stringify({ ts: 1000, seq: 0, type: 'session.start', session_id: sessionId1, data: { iteration: 1 } }),
